var ML = window.__ML || (window.__ML = {});

ML.pill = function(i, value, unit, tone){
  MSD.q('#ml-pill-v-' + i).textContent = value;
  if(unit !== null) MSD.qa('#ml-pill-' + i + ' .ml-pill-u')[0].textContent = unit;
  MSD.cls('#ml-pill-' + i, 'bad', tone === 'bad');
  MSD.cls('#ml-pill-' + i, 'good', tone === 'good');
};

// Which nodes exist, and which one this stage is about.
ML.nodes = function(list, live){
  ['app','fd','api','db','entra'].forEach(function(n){
    MSD.cls('#ml-n-' + n, 'on', list.indexOf(n) !== -1);
    MSD.cls('#ml-n-' + n, 'live', (live || []).indexOf(n) !== -1);
  });
};

// Wires: on = drawn, flow = dots moving, dead = drawn but faded.
ML.wires = function(map){
  ['direct','a1','a2','a3','entra'].forEach(function(id){
    var v = map[id] || ['off', ''];
    var el = '#ml-w-' + id;
    MSD.cls(el, 'on',   v[0] !== 'off');
    MSD.cls(el, 'flow', v[0] === 'flow');
    MSD.cls(el, 'dead', v[0] === 'dead');
    MSD.cls(el, 'hot',  v[1] === 'hot');
    MSD.cls(el, 'bad',  v[1] === 'bad');
  });
};

ML.cnt = function(node, value){
  var el = '#ml-c-' + node;
  MSD.cls(el, 'on', value !== null);
  if(value !== null) MSD.q(el).textContent = value;
};

// The code block. lines is an array of HTML strings; active is 1-based.
ML.code = function(file, lines, active, gone, tone){
  MSD.q('#ml-code-h').textContent = file;
  for(var i = 1; i <= 5; i++){
    MSD.q('#ml-ln-' + i).innerHTML = lines[i - 1] || '';
    MSD.cls('#ml-ln-' + i, 'active', i === active);
    MSD.cls('#ml-ln-' + i, 'gone', (gone || []).indexOf(i) !== -1);
  }
  MSD.cls('#ml-code', 'bad', tone === 'bad');
  MSD.cls('#ml-code', 'good', tone === 'good');
};

ML.OPEN = [
  '<span class="c">// "it came from our app, so it is fine"</span>',
  '<span class="k">if</span> (origin.<span class="f">Contains</span>(<span class="s">"msdevbuild.com"</span>)',
  ' || client == <span class="s">"msdevbuild-mobile"</span>)',
  '    <span class="k">await</span> next();',
  '<span class="c">// both are headers. curl sets either one.</span>'
];

ML.SAFE = [
  '<span class="c">// the caller gets an identity, not an account</span>',
  '[<span class="s">"sub"</span>]   = <span class="s">$"guest:{Guid.NewGuid():n}"</span>,',
  '[<span class="s">"scope"</span>] = <span class="s">"catalog.read"</span>,',
  'Expires = DateTime.UtcNow.<span class="f">AddMinutes</span>(15)',
  '<span class="c">// 15 minutes. countable. revocable.</span>'
];


MSD.cls('#ml-map', 'dim', false);
MSD.cls('#ml-payoff', 'on', false);
MSD.cls('#ml-cut', 'on', false);

ML.pill(1, '1', 'caller', '');
ML.pill(2, 'none', '', '');
ML.nodes(['app', 'fd'], ['app']);
ML.wires({ direct: ['flow', ''] });
ML.cnt('app', null); ML.cnt('fd', null); ML.cnt('api', null);
ML.cnt('entra', null); ML.cnt('db', null);
ML.code('the middleware that was not a gate', ML.OPEN, 1, [], '');

MSD.after(400,  function(){ MSD.sfx.whoosh(); });
MSD.after(1400, function(){ MSD.punch('#ml-n-fd', 3); MSD.sfx.blip(3); });

var ML = window.__ML;
ML.pill(1, '1', 'caller', '');
ML.pill(2, 'header', '', 'bad');
ML.nodes(['app', 'fd', 'api'], ['api']);
ML.wires({ direct: ['flow', ''], a1: ['on', ''] });
ML.code('the middleware that was not a gate', ML.OPEN, 2, [], 'bad');
MSD.after(500,  function(){ MSD.punch('#ml-ln-2', 3); MSD.sfx.blip(2); });
MSD.after(1500, function(){ MSD.punch('#ml-ln-3', 3); });

var ML = window.__ML;
ML.pill(1, '2', 'identical', 'bad');
ML.pill(2, 'none', '', 'bad');
ML.nodes(['app', 'fd', 'api'], ['fd']);
ML.wires({ direct: ['flow', ''], a1: ['flow', 'bad'] });
ML.cnt('fd', '2');
ML.code('the middleware that was not a gate', ML.OPEN, 5, [], 'bad');
MSD.after(400,  function(){ MSD.punch('#ml-n-fd', 4); MSD.sfx.whoosh(); });
MSD.after(1400, function(){ MSD.punch('#ml-ln-5', 3); MSD.sfx.blip(3); });

var ML = window.__ML;
ML.pill(1, '2', 'identical', 'bad');
ML.pill(2, 'none', '', 'bad');
ML.nodes(['app', 'fd', 'api', 'db'], ['api']);
ML.wires({ direct: ['flow', 'bad'], a1: ['flow', 'bad'], a2: ['flow', 'bad'] });
ML.cnt('db', '60');
MSD.after(600,  function(){ MSD.punch('#ml-n-api', 3); MSD.sfx.blip(3); });
MSD.after(1500, function(){ MSD.punch('#ml-c-db', 4); });

var ML = window.__ML;
ML.pill(1, '180k', 'a day', 'bad');
ML.pill(2, 'none', '', 'bad');
ML.nodes(['app', 'fd', 'api', 'db'], ['db']);
ML.wires({ direct: ['flow', 'bad'], a1: ['flow', 'bad'], a2: ['flow', 'bad'] });
ML.cnt('db', '429');
MSD.after(500,  function(){ MSD.punch('#ml-n-db', 4); MSD.sfx.blip(2); });

var ML = window.__ML;
ML.pill(1, '2', 'identical', 'bad');
ML.pill(2, 'guest', '', '');
ML.nodes(['app', 'fd', 'api', 'entra'], ['entra']);
ML.wires({ direct: ['flow', ''], a1: ['flow', 'bad'], entra: ['on', ''] });
ML.code('issue a token with no account behind it', ML.SAFE, 1, [], '');
MSD.after(500,  function(){ MSD.punch('#ml-n-entra', 4); MSD.sfx.whoosh(); });

var ML = window.__ML;
ML.pill(1, '2', 'identical', '');
ML.pill(2, 'guest', '', 'good');
ML.nodes(['app', 'fd', 'api', 'entra', 'db'], ['entra']);
ML.wires({ direct: ['flow', ''], a1: ['dead', ''], entra: ['flow', ''], a2: ['flow', ''] });
ML.cnt('entra', '15m');
ML.code('issue a token with no account behind it', ML.SAFE, 3, [], 'good');
MSD.cls('#ml-cut', 'on', true);
MSD.after(500,  function(){ MSD.punch('#ml-cut', 4); MSD.sfx.blip(4); });
MSD.after(1500, function(){ MSD.punch('#ml-ln-3', 3); });

var ML = window.__ML;
ML.pill(1, '60', 'per min', 'good');
ML.pill(2, 'guest', '', 'good');
ML.nodes(['app', 'fd', 'api', 'entra', 'db'], ['api']);
ML.wires({ direct: ['flow', ''], a1: ['dead', ''], entra: ['on', ''], a2: ['flow', ''] });
ML.cnt('db', '4');
MSD.after(400, function(){
  MSD.cls('#ml-map', 'dim', true);
  MSD.cls('#ml-payoff', 'on', true);
  MSD.sfx.whoosh();
});
MSD.after(1200, function(){ MSD.punch('#ml-payoff', 3); MSD.sfx.blip(4); });
